"""数据层领域模型：Gamma 市场元数据、盘口档位、WebSocket 行情事件。

价格/数量统一用 ``Decimal``，避免浮点误差。Gamma 的 ``outcomes`` /
``clobTokenIds`` 是 JSON 编码字符串，这里在入库时自动解析成 list。
"""

from __future__ import annotations

import json
from decimal import Decimal
from typing import Any

from pydantic import BaseModel, ConfigDict, Field, field_validator


def _maybe_json_list(v: Any) -> Any:
    """Gamma 的 outcomes/clobTokenIds 可能是 JSON 字符串，也可能已是 list。"""
    if isinstance(v, str):
        s = v.strip()
        if s.startswith("["):
            return json.loads(s)
    return v


class Token(BaseModel):
    """一个 outcome 对应的可交易 token（YES/NO 或 Up/Down）。"""

    token_id: str
    outcome: str


class Market(BaseModel):
    """Gamma ``/markets`` 返回的单个市场。"""

    model_config = ConfigDict(populate_by_name=True, extra="ignore")

    id: str
    question: str = ""
    slug: str = ""
    condition_id: str = Field(default="", alias="conditionId")
    neg_risk: bool = Field(default=False, alias="negRisk")
    active: bool = True
    closed: bool = False
    outcomes: list[str] = Field(default_factory=list)
    clob_token_ids: list[str] = Field(default_factory=list, alias="clobTokenIds")
    liquidity: Decimal = Field(default=Decimal("0"), alias="liquidityNum")

    @field_validator("outcomes", "clob_token_ids", mode="before")
    @classmethod
    def _parse_json_list(cls, v: Any) -> Any:
        return _maybe_json_list(v)

    @field_validator("liquidity", mode="before")
    @classmethod
    def _empty_liquidity_to_zero(cls, v: Any) -> Any:
        # Gamma 偶尔返回空串/None
        if v is None or v == "":
            return Decimal("0")
        return v

    @property
    def tokens(self) -> list[Token]:
        """token_id 与 outcome 一一对应。"""
        return [
            Token(token_id=tid, outcome=out)
            for tid, out in zip(self.clob_token_ids, self.outcomes)
        ]

    @property
    def is_tradeable(self) -> bool:
        """活跃、未结算、且有完整的双边 token。"""
        return bool(self.active and not self.closed and len(self.clob_token_ids) >= 2)


class BookLevel(BaseModel):
    """一档盘口：价格 + 该档挂单量。"""

    price: Decimal
    size: Decimal


class WsBookEvent(BaseModel):
    """``book`` 事件：某 token 的 L2 全量快照。"""

    asset_id: str
    market: str = ""
    bids: list[BookLevel] = Field(default_factory=list)
    asks: list[BookLevel] = Field(default_factory=list)
    timestamp: str = ""
    hash: str = ""


class WsPriceChange(BaseModel):
    """``price_change`` 事件：单档增量。``side`` BUY=bid 侧，SELL=ask 侧。

    ``size == 0`` 表示该档被撤销。
    """

    asset_id: str
    side: str  # "BUY" / "SELL"
    price: Decimal
    size: Decimal
    timestamp: str = ""
    hash: str = ""

    @property
    def is_removal(self) -> bool:
        return self.size == 0


class WsLastTrade(BaseModel):
    """``last_trade_price`` 事件：一笔成交流。"""

    asset_id: str
    price: Decimal
    size: Decimal
    side: str = ""
    timestamp: str = ""

