"""本地 L2 订单簿：``book`` 快照全量覆盖 + ``price_change`` 增量维护。

- 收到快照前的增量一律丢弃（服务端会在订阅后先推快照）；
- 增量 ``size == 0`` 表示撤档，从对应侧删除该价格；
- bid/ask 各维护 ``价格 -> 挂单量`` 的有序映射。
"""

from __future__ import annotations

from decimal import Decimal

from pydantic import BaseModel, Field

from pm_arb.data.models import BookLevel, WsBookEvent, WsPriceChange


class BookSnapshot(BaseModel):
    """订单簿状态：bid/ask 各为 价格(Decimal) -> 数量(Decimal) 的映射。"""

    bids: dict[Decimal, Decimal] = Field(default_factory=dict)
    asks: dict[Decimal, Decimal] = Field(default_factory=dict)


class LocalOrderBook:
    """单个 token 的本地订单簿。"""

    def __init__(self, asset_id: str) -> None:
        self.asset_id = asset_id
        self._snapshot = BookSnapshot()
        self.ready: bool = False

    @property
    def snapshot(self) -> BookSnapshot:
        return self._snapshot

    # ---- 更新 ----

    def apply_snapshot(self, ev: WsBookEvent) -> None:
        """全量快照：完全覆盖旧状态。"""
        snap = BookSnapshot()
        for lvl in ev.bids:
            if lvl.size > 0:
                snap.bids[lvl.price] = lvl.size
        for lvl in ev.asks:
            if lvl.size > 0:
                snap.asks[lvl.price] = lvl.size
        self._snapshot = snap
        self.ready = True

    def apply_change(self, ev: WsPriceChange) -> None:
        """增量更新；快照到达前的增量直接丢弃。"""
        if not self.ready:
            return
        book = self._snapshot.bids if ev.side.upper() == "BUY" else self._snapshot.asks
        if ev.size == 0:
            book.pop(ev.price, None)  # 撤档
        else:
            book[ev.price] = ev.size

    # ---- 最优价 / 派生量 ----

    @property
    def best_bid(self) -> BookLevel | None:
        if not self._snapshot.bids:
            return None
        price = max(self._snapshot.bids)
        return BookLevel(price=price, size=self._snapshot.bids[price])

    @property
    def best_ask(self) -> BookLevel | None:
        if not self._snapshot.asks:
            return None
        price = min(self._snapshot.asks)
        return BookLevel(price=price, size=self._snapshot.asks[price])

    @property
    def spread(self) -> Decimal | None:
        bb, ba = self.best_bid, self.best_ask
        if bb is None or ba is None:
            return None
        return ba.price - bb.price

    @property
    def midpoint(self) -> Decimal | None:
        bb, ba = self.best_bid, self.best_ask
        if bb is None or ba is None:
            return None
        return (bb.price + bb.price) / 2 if False else (bb.price + ba.price) / 2

    def top_levels(self, n: int) -> tuple[list[BookLevel], list[BookLevel]]:
        """返回前 n 档：bids 按价格降序、asks 按价格升序。"""
        bids = sorted(self._snapshot.bids.items(), key=lambda kv: kv[0], reverse=True)[:n]
        asks = sorted(self._snapshot.asks.items(), key=lambda kv: kv[0])[:n]
        return (
            [BookLevel(price=p, size=s) for p, s in bids],
            [BookLevel(price=p, size=s) for p, s in asks],
        )

